CREATE TYPE "CommercialLineType" AS ENUM ('PRODUCT','SERVICE','WORK_PACKAGE','CUSTOM','MATERIAL','SUBCONTRACT');
CREATE TYPE "DiscountType" AS ENUM ('PERCENTAGE','FIXED'); CREATE TYPE "PurchasePurpose" AS ENUM ('OFFICE','PROJECT'); CREATE TYPE "PurchaseClassification" AS ENUM ('PURCHASE_COST','GENERAL_EXPENSES'); CREATE TYPE "PaymentMode" AS ENUM ('CASH','BANK'); CREATE TYPE "SettlementStatus" AS ENUM ('POSTED'); CREATE TYPE "PaymentReminderStatus" AS ENUM ('PENDING','SENT','DISMISSED');
CREATE TYPE "CommercialAuditEventType" AS ENUM ('DOCUMENT_CREATED','INVOICE_POSTED','CREDIT_NOTE_POSTED','PURCHASE_BILL_POSTED','DEBIT_NOTE_POSTED','CUSTOMER_RECEIPT_POSTED','CUSTOMER_ADVANCE_POSTED','CUSTOMER_ADVANCE_APPLIED','VENDOR_PAYMENT_POSTED','VENDOR_ADVANCE_POSTED','VENDOR_ADVANCE_APPLIED','REMINDER_CREATED','REMINDER_STATUS_CHANGED');
ALTER TABLE "commercial_documents" ADD COLUMN "customerId" UUID, ADD COLUMN "vendorId" UUID, ADD COLUMN "sourceDocumentId" UUID, ADD COLUMN "purchasePurpose" "PurchasePurpose", ADD COLUMN "purchaseClassification" "PurchaseClassification", ADD COLUMN "projectReference" VARCHAR(240), ADD COLUMN "discountTotal" DECIMAL(18,2) NOT NULL DEFAULT 0, ADD COLUMN "taxableTotal" DECIMAL(18,2);
UPDATE "commercial_documents" SET "customerId"="partyId" WHERE "type" IN ('SALES_ORDER','PROFORMA_INVOICE','SALES_INVOICE','DELIVERY_CHALLAN','CREDIT_NOTE'); UPDATE "commercial_documents" SET "vendorId"="partyId", "purchasePurpose"='OFFICE', "purchaseClassification"='PURCHASE_COST' WHERE "type" IN ('PURCHASE_ORDER','PURCHASE_BILL','DEBIT_NOTE','SUBCONTRACT_PURCHASE'); UPDATE "commercial_documents" SET "taxableTotal"="subtotal"; ALTER TABLE "commercial_documents" ALTER COLUMN "taxableTotal" SET NOT NULL;
ALTER TABLE "commercial_document_lines" RENAME COLUMN "taxable" TO "taxableAmount"; ALTER TABLE "commercial_document_lines" RENAME COLUMN "total" TO "lineTotal"; ALTER TABLE "commercial_document_lines" ADD COLUMN "lineType" "CommercialLineType", ADD COLUMN "productId" UUID, ADD COLUMN "serviceId" UUID, ADD COLUMN "workPackageId" UUID, ADD COLUMN "itemName" VARCHAR(240), ADD COLUMN "itemCode" VARCHAR(80), ADD COLUMN "specification" TEXT, ADD COLUMN "unitName" VARCHAR(80), ADD COLUMN "unitSymbol" VARCHAR(20), ADD COLUMN "discountType" "DiscountType", ADD COLUMN "discountValue" DECIMAL(18,4), ADD COLUMN "baseAmount" DECIMAL(18,2), ADD COLUMN "discountAmount" DECIMAL(18,2) NOT NULL DEFAULT 0;
UPDATE "commercial_document_lines" SET "lineType"='CUSTOM',"itemName"=COALESCE("description",'Custom'),"baseAmount"="quantity"*"rate"; ALTER TABLE "commercial_document_lines" ALTER COLUMN "lineType" SET NOT NULL, ALTER COLUMN "itemName" SET NOT NULL, ALTER COLUMN "baseAmount" SET NOT NULL, ALTER COLUMN "description" DROP NOT NULL;
ALTER TABLE "account_settlements" ADD COLUMN "customerId" UUID, ADD COLUMN "vendorId" UUID, ADD COLUMN "idempotencyKey" VARCHAR(120); UPDATE "account_settlements" SET "customerId"="partyId" WHERE "type" IN ('CUSTOMER_RECEIPT','CUSTOMER_ADVANCE'); UPDATE "account_settlements" SET "vendorId"="partyId" WHERE "type" IN ('VENDOR_PAYMENT','VENDOR_ADVANCE'); UPDATE "account_settlements" SET "idempotencyKey"='legacy-'||"id"::text; ALTER TABLE "account_settlements" ALTER COLUMN "idempotencyKey" SET NOT NULL;
ALTER TABLE "account_settlements" ADD COLUMN "status" "SettlementStatus" NOT NULL DEFAULT 'POSTED', ADD COLUMN "settlementNumber" VARCHAR(100), ADD COLUMN "paymentMode" "PaymentMode", ADD COLUMN "remainingAmount" DECIMAL(18,2) NOT NULL DEFAULT 0, ADD COLUMN "notes" TEXT; UPDATE "account_settlements" SET "settlementNumber"='LEGACY-'||"id"::text,"paymentMode"='BANK',"remainingAmount"=CASE WHEN "type" IN ('CUSTOMER_ADVANCE','VENDOR_ADVANCE') THEN "amount" ELSE 0 END; ALTER TABLE "account_settlements" ALTER COLUMN "settlementNumber" SET NOT NULL, ALTER COLUMN "paymentMode" SET NOT NULL;
ALTER TABLE "payment_reminders" ADD COLUMN "customerId" UUID, ADD COLUMN "status" "PaymentReminderStatus" NOT NULL DEFAULT 'PENDING', ADD COLUMN "createdById" UUID, ADD COLUMN "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP; UPDATE "payment_reminders" r SET "customerId"=d."customerId","createdById"=d."createdById" FROM "commercial_documents" d WHERE d.id=r."documentId"; ALTER TABLE "payment_reminders" ALTER COLUMN "customerId" SET NOT NULL, ALTER COLUMN "createdById" SET NOT NULL;
CREATE TABLE "settlement_allocations" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"companyId" UUID NOT NULL,"settlementId" UUID NOT NULL,"documentId" UUID NOT NULL,"amount" DECIMAL(18,2) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("companyId","settlementId","documentId"));
CREATE TABLE "advance_applications" ("id" UUID PRIMARY KEY,"companyId" UUID NOT NULL,"advanceId" UUID NOT NULL,"documentId" UUID NOT NULL,"amount" DECIMAL(18,2) NOT NULL,"applicationDate" DATE NOT NULL,"idempotencyKey" VARCHAR(120) NOT NULL,"journalEntryId" UUID NOT NULL,"createdById" UUID NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("companyId","idempotencyKey"),UNIQUE("companyId","advanceId","documentId","idempotencyKey"));
CREATE TABLE "commercial_audit_events" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"companyId" UUID NOT NULL,"eventType" "CommercialAuditEventType" NOT NULL,"entityType" VARCHAR(60) NOT NULL,"entityId" UUID NOT NULL,"actorId" UUID,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS "vendors_companyId_id_key" ON "vendors"("companyId","id"); ALTER TABLE "commercial_documents" ADD FOREIGN KEY("companyId","customerId") REFERENCES "customers"("companyId","id") ON DELETE RESTRICT, ADD FOREIGN KEY("companyId","vendorId") REFERENCES "vendors"("companyId","id") ON DELETE RESTRICT, ADD FOREIGN KEY("companyId","journalEntryId") REFERENCES "journal_entries"("companyId","id") ON DELETE RESTRICT, ADD FOREIGN KEY("companyId","sourceDocumentId") REFERENCES "commercial_documents"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE "commercial_document_lines" ADD FOREIGN KEY("companyId","productId") REFERENCES "account_products"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT, ADD FOREIGN KEY("companyId","serviceId") REFERENCES "account_services"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT, ADD FOREIGN KEY("companyId","workPackageId") REFERENCES "work_packages"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM "account_settlements" WHERE "journalEntryId" IS NULL) THEN RAISE EXCEPTION 'Cannot harden settlements: legacy row lacks authoritative journal'; END IF; END $$; ALTER TABLE "account_settlements" ALTER COLUMN "journalEntryId" SET NOT NULL;
CREATE UNIQUE INDEX "account_settlements_companyId_id_key" ON "account_settlements"("companyId","id"); CREATE UNIQUE INDEX "account_settlements_companyId_idempotencyKey_key" ON "account_settlements"("companyId","idempotencyKey");
ALTER TABLE "account_settlements" ADD FOREIGN KEY("companyId","journalEntryId") REFERENCES "journal_entries"("companyId","id") ON DELETE RESTRICT, ADD FOREIGN KEY("companyId","customerId") REFERENCES "customers"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT, ADD FOREIGN KEY("companyId","vendorId") REFERENCES "vendors"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT; ALTER TABLE "advance_applications" ADD FOREIGN KEY("companyId","journalEntryId") REFERENCES "journal_entries"("companyId","id") ON DELETE RESTRICT; ALTER TABLE "settlement_allocations" ADD FOREIGN KEY("companyId") REFERENCES "companies"("id") ON DELETE RESTRICT, ADD FOREIGN KEY("companyId","settlementId") REFERENCES "account_settlements"("companyId","id") ON DELETE RESTRICT, ADD FOREIGN KEY("companyId","documentId") REFERENCES "commercial_documents"("companyId","id") ON DELETE RESTRICT;
ALTER TABLE "advance_applications" ADD FOREIGN KEY("companyId") REFERENCES "companies"("id") ON DELETE RESTRICT, ADD FOREIGN KEY("companyId","advanceId") REFERENCES "account_settlements"("companyId","id") ON DELETE RESTRICT, ADD FOREIGN KEY("companyId","documentId") REFERENCES "commercial_documents"("companyId","id") ON DELETE RESTRICT, ADD FOREIGN KEY("companyId","createdById") REFERENCES "users"("companyId","id") ON DELETE RESTRICT;
ALTER TABLE "payment_reminders" ADD FOREIGN KEY("companyId","customerId") REFERENCES "customers"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE "commercial_audit_events" ADD FOREIGN KEY("companyId") REFERENCES "companies"("id") ON DELETE RESTRICT, ADD FOREIGN KEY("companyId","actorId") REFERENCES "users"("companyId","id") ON DELETE RESTRICT; ALTER TABLE "payment_reminders" ADD FOREIGN KEY("companyId","createdById") REFERENCES "users"("companyId","id") ON DELETE RESTRICT;
ALTER TABLE "account_settlements" ADD CONSTRAINT "settlement_party_exactly_one" CHECK (("type" IN ('CUSTOMER_RECEIPT','CUSTOMER_ADVANCE') AND "customerId" IS NOT NULL AND "vendorId" IS NULL AND "partyId"="customerId") OR ("type" IN ('VENDOR_PAYMENT','VENDOR_ADVANCE') AND "vendorId" IS NOT NULL AND "customerId" IS NULL AND "partyId"="vendorId"));
ALTER TABLE "commercial_documents" ADD CONSTRAINT "commercial_party_exactly_one" CHECK (("customerId" IS NOT NULL)::int+("vendorId" IS NOT NULL)::int=1), ADD CONSTRAINT "commercial_project_reference" CHECK ("purchasePurpose" IS DISTINCT FROM 'PROJECT' OR length(trim("projectReference"))>0), ADD CONSTRAINT "commercial_totals_nonnegative" CHECK ("subtotal">=0 AND "discountTotal">=0 AND "taxableTotal">=0 AND "taxTotal">=0 AND "grandTotal">=0);
ALTER TABLE "commercial_document_lines" ADD CONSTRAINT "commercial_line_positive" CHECK ("quantity">0 AND "rate">=0 AND "taxRate">=0 AND "discountAmount">=0 AND "baseAmount">=0 AND "taxableAmount">=0 AND "taxAmount">=0 AND "lineTotal">=0), ADD CONSTRAINT "commercial_line_source_consistent" CHECK (("lineType" IN ('PRODUCT','MATERIAL') AND "productId" IS NOT NULL AND "serviceId" IS NULL AND "workPackageId" IS NULL) OR ("lineType"='SERVICE' AND "serviceId" IS NOT NULL AND "productId" IS NULL AND "workPackageId" IS NULL) OR ("lineType" IN ('WORK_PACKAGE','SUBCONTRACT') AND "workPackageId" IS NOT NULL AND "productId" IS NULL AND "serviceId" IS NULL) OR ("lineType"='CUSTOM' AND "productId" IS NULL AND "serviceId" IS NULL AND "workPackageId" IS NULL));
ALTER TABLE "account_settlements" ADD CONSTRAINT "settlement_positive" CHECK ("amount">0 AND "remainingAmount">=0 AND "remainingAmount"<="amount"); ALTER TABLE "settlement_allocations" ADD CONSTRAINT "allocation_positive" CHECK ("amount">0); ALTER TABLE "advance_applications" ADD CONSTRAINT "advance_application_positive" CHECK ("amount">0);
CREATE UNIQUE INDEX "account_settlement_number_key" ON "account_settlements"("companyId","branchId","type","settlementNumber");
INSERT INTO "ledger_accounts" ("id","companyId","code","name","accountClass","normalBalance","systemKey","isSystem","isActive","allowPosting","createdAt","updatedAt") SELECT gen_random_uuid(),c.id,'1450','Input Tax Credit','ASSET','DEBIT','INPUT_TAX_CREDIT',true,true,true,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM "companies" c WHERE c."productEdition" IN ('SALESPUNCH360_ACCOUNT','SALESPUNCH360_PLUS') ON CONFLICT ("companyId","systemKey") DO NOTHING;
INSERT INTO "ledger_accounts" ("id","companyId","code","name","accountClass","normalBalance","systemKey","isSystem","isActive","allowPosting","createdAt","updatedAt") SELECT gen_random_uuid(),c.id,'2150','Customer Advances','LIABILITY','CREDIT','CUSTOMER_ADVANCES',true,true,true,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM "companies" c WHERE c."productEdition" IN ('SALESPUNCH360_ACCOUNT','SALESPUNCH360_PLUS') ON CONFLICT ("companyId","systemKey") DO NOTHING;
CREATE FUNCTION prevent_financial_history_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF current_setting('app.account_cleanup_company_id',true)=OLD."companyId"::text AND TG_OP='DELETE' THEN RETURN OLD; END IF; RAISE EXCEPTION 'FINANCIAL_HISTORY_IMMUTABLE'; END $$;
CREATE TRIGGER commercial_posted_immutable BEFORE UPDATE OR DELETE ON "commercial_documents" FOR EACH ROW WHEN (OLD."status"='POSTED') EXECUTE FUNCTION prevent_financial_history_mutation(); CREATE TRIGGER settlement_immutable BEFORE DELETE ON "account_settlements" FOR EACH ROW EXECUTE FUNCTION prevent_financial_history_mutation(); CREATE FUNCTION guard_settlement_update() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW."remainingAmount" <= OLD."remainingAmount" AND NEW."id"=OLD."id" AND NEW."companyId"=OLD."companyId" AND NEW."branchId"=OLD."branchId" AND NEW."type"=OLD."type" AND NEW."status"=OLD."status" AND NEW."settlementNumber"=OLD."settlementNumber" AND NEW."partyId"=OLD."partyId" AND NEW."paymentMode"=OLD."paymentMode" AND NEW."amount"=OLD."amount" AND NEW."transactionDate"=OLD."transactionDate" AND NEW."journalEntryId"=OLD."journalEntryId" AND NEW."createdById"=OLD."createdById" THEN RETURN NEW; END IF; RAISE EXCEPTION 'FINANCIAL_HISTORY_IMMUTABLE'; END $$; CREATE TRIGGER settlement_update_guard BEFORE UPDATE ON "account_settlements" FOR EACH ROW EXECUTE FUNCTION guard_settlement_update(); CREATE TRIGGER commercial_audit_append_only BEFORE UPDATE OR DELETE ON "commercial_audit_events" FOR EACH ROW EXECUTE FUNCTION prevent_financial_history_mutation();

CREATE FUNCTION guard_commercial_line_history() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE cid uuid; did uuid; posted boolean; BEGIN IF TG_OP='INSERT' THEN cid=NEW."companyId"; did=NEW."documentId"; ELSE cid=OLD."companyId"; did=OLD."documentId"; END IF; IF TG_OP='UPDATE' AND (NEW."companyId",NEW."documentId") IS DISTINCT FROM (OLD."companyId",OLD."documentId") THEN RAISE EXCEPTION 'FINANCIAL_HISTORY_IMMUTABLE'; END IF; IF TG_OP='DELETE' AND current_setting('app.account_cleanup_company_id',true)=cid::text THEN RETURN OLD; END IF; SELECT ("status"='POSTED') INTO posted FROM "commercial_documents" WHERE "companyId"=cid AND "id"=did; IF posted THEN RAISE EXCEPTION 'FINANCIAL_HISTORY_IMMUTABLE'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER commercial_line_history_guard BEFORE INSERT OR UPDATE OR DELETE ON "commercial_document_lines" FOR EACH ROW EXECUTE FUNCTION guard_commercial_line_history();
CREATE TRIGGER settlement_allocation_append_only BEFORE UPDATE OR DELETE ON "settlement_allocations" FOR EACH ROW EXECUTE FUNCTION prevent_financial_history_mutation();
CREATE FUNCTION guard_settlement_allocation_insert() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF current_setting('app.financial_write_company_id',true)=NEW."companyId"::text THEN RETURN NEW; END IF; IF EXISTS(SELECT 1 FROM "account_settlements" WHERE "companyId"=NEW."companyId" AND "id"=NEW."settlementId") THEN RAISE EXCEPTION 'FINANCIAL_HISTORY_IMMUTABLE'; END IF; RETURN NEW; END $$; CREATE TRIGGER settlement_allocation_insert_guard BEFORE INSERT ON "settlement_allocations" FOR EACH ROW EXECUTE FUNCTION guard_settlement_allocation_insert();
CREATE TRIGGER advance_application_append_only BEFORE UPDATE OR DELETE ON "advance_applications" FOR EACH ROW EXECUTE FUNCTION prevent_financial_history_mutation();
